s=s[:start]+'''      <header className="e2e_record_hero reference-profile-hero"><div className="reference-person"><div className="e2e_record_avatar">{employee.profile_photo_url?<img src={employee.profile_photo_url} alt={employee.legal_name||"Employee"}/>:<FaUser/>}<i aria-hidden="true"/></div><div className="reference-person-copy"><div className="reference-name-line"><h1>{employee.legal_name||[employee.firstname,employee.lastname].filter(Boolean).join(" ")}</h1><strong className="reference-status">{employee.user_status|| (employee.user_id?"Assigned":"Not Assigned")}</strong></div><h2>{employee.position_name||employee.position||employee.role||"Position not assigned"}</h2><div className="reference-contact-line"><span><FaEnvelope/>{normalizeCollection(employee.collection).email||employee.payroll_email||"Email not provided"}</span><span><FaPhone/>{employee.contact_info||"Phone not provided"}</span><span><FaMapMarkerAlt/>{employee.payroll_profile?.location||employee.address||"Location not provided"}</span><span><FaCalendarAlt/>Joined {employee.date_of_joining||employee.joining_date||"Not recorded"}</span></div></div></div>
      {isOwn&&canViewAttendance?<EmployeeAttendanceSwitch compact employeeCode={employee.employee_id} onViewAttendance={()=>setShowAttendance(true)} onChanged={()=>setAttendanceRevision(n=>n+1)}/>:canViewAttendance?<section className="reference-today-card"><h2>Attendance (Today)</h2><p>View this employee's attendance records.</p><button type="button" onClick={()=>setShowAttendance(true)}>View Attendance</button></section>:null}</header>
      <nav className="employee-profile-actions reference-profile-tabs" aria-label="Profile sections"><a className="active" href="#profile-overview"><FaHome/>Overview</a><a href="#profile-details"><FaUser/>Personal</a><a href="#profile-employment"><FaBriefcase/>Employment</a><a href="#profile-projects"><FaBriefcase/>Projects</a><a href="#profile-performance"><FaChartLine/>Performance</a><button type="button" onClick={()=>setShowAttendance(value=>!value)} aria-expanded={showAttendance}><FaClock/>Time Tracking</button><a href="#profile-education"><FaGraduationCap/>Education</a><a href="#profile-documents"><FaFileAlt/>Documents</a><a href="#profile-activity"><FaCalendarAlt/>Activity</a></nav>
      <EmployeeProfileOverview employee={employee} attendance={monthly} attendanceError={monthlyError} canViewAttendance={canViewAttendance}/>
''' + s[end:]
s=s.replace('canManageDocuments={can("employees","edit")&&scope("employees")==="ALL"}/>', 'canManageDocuments={can("employees","edit")&&scope("employees")==="ALL"} overview={<EmployeeProfileOverview details employee={employee} attendance={monthly} attendanceError={monthlyError} canViewAttendance={canViewAttendance}/>}/>')
p.write_text(s,encoding='utf-8')
