new='[["Full Name",employee.legal_name||[employee.firstname,employee.lastname].filter(Boolean).join(" ")],["Personal Email",c.email||employee.payroll_email],["Phone Number",employee.contact_info],["Date of Birth",employee.birthdate==="0000-00-00"?"":employee.birthdate],["Gender",employee.gender],["Permanent Address",employee.address],["Current Address",c.current_address],["Facebook Profile",c.facebook_profile]]'
s=s.replace(old,new)
marker=' <Card id="profile-family"'
